package com.owuor.educue.certificate.entity;
import com.owuor.educue.certificate.enums.CertificateJobStatus;import com.owuor.educue.graduation.entity.GraduationBatch;import com.owuor.educue.users.entity.User;import jakarta.persistence.*;import lombok.*;import java.time.*;import java.util.*;
@Entity @Table(name="certificate_generation_jobs",uniqueConstraints=@UniqueConstraint(name="uq_certificate_job_batch",columnNames="graduation_batch_id")) @Getter @Setter @NoArgsConstructor
public class CertificateGenerationJob{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true,updatable=false)private UUID uuid=UUID.randomUUID();@OneToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="graduation_batch_id",nullable=false)private GraduationBatch batch;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private CertificateJobStatus status=CertificateJobStatus.QUEUED;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="requested_by",nullable=false)private User requestedBy;@Column(name="total_certificates",nullable=false)private int totalCertificates;@Column(name="processed_certificates",nullable=false)private int processedCertificates;@Column(name="successful_certificates",nullable=false)private int successfulCertificates;@Column(name="failed_certificates",nullable=false)private int failedCertificates;@Column(name="error_message",length=1000)private String errorMessage;@Column(name="requested_at",nullable=false,updatable=false)private LocalDateTime requestedAt=LocalDateTime.now();@Column(name="started_at")private LocalDateTime startedAt;@Column(name="completed_at")private LocalDateTime completedAt;@Version private Long version;}
